int lowbit(unsigned int n) {
    /**
     *  10100  20
     *  01100  two's complement of 20
     * &------
     *  00100->lowbit
    */
    unsigned int complement_n = ~n + 1; // To get two's complement, if it's an int just use -n
    return n & complement_n; 
}
// or

int lowbit(int n) {
    return n & (-n)
}

